cd /tmp/devflow-34-05-capture
PHASE_DIR="/tmp/devflow-34-05-capture/.planning/phases/01-add-probe-marker"
PADDED_PHASE="01"
REVIEW_DEPTH="standard"

# Tier 2 - SUMMARY.md extraction
SUMMARIES=$(ls "${PHASE_DIR}"/*-SUMMARY.md 2>/dev/null)
REVIEW_FILES=()
for summary in $SUMMARIES; do
  EXTRACTED=$(node -e "
    const fs = require('fs');
    const content = fs.readFileSync('$summary', 'utf-8');
    const match = content.replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---/);
    if (!match) { process.exit(0); }
    const yaml = match[1];
    const files = [];
    let inSection = null;
    for (const line of yaml.split('\n')) {
      if (/^\s+created:/.test(line)) { inSection = 'created'; continue; }
      if (/^\s+modified:/.test(line)) { inSection = 'modified'; continue; }
      if (/^\s*[\w-]+:/.test(line) && !/^\s*-/.test(line)) { inSection = null; continue; }
      if (inSection && /^\s+-\s+(.+)/.test(line)) {
        let raw = line.match(/^\s+-\s+(.+)/)[1].trim();
        raw = raw.replace(/^['\"]|['\"]\$/g, '');
        raw = raw.replace(/\s+\([^)]*\)\s*\$/, '');
        raw = raw.split(/\s+—\s/)[0].trim();
        const KNOWN=new Set(['dockerfile','containerfile','makefile','justfile','procfile']);
        const hasExtension = /\.[A-Za-z0-9]+\$/.test(raw);
        const basename = raw.split('/').pop().toLowerCase();
        if (hasExtension || KNOWN.has(basename)) files.push(raw);
      }
    }
    if (files.length) console.log(files.join('\n'));
  " 2>/dev/null)
  if [ -n "$EXTRACTED" ]; then
    while IFS= read -r file; do [ -n "$file" ] && REVIEW_FILES+=("$file"); done <<< "$EXTRACTED"
  fi
done
echo "SUMMARY-extracted: ${REVIEW_FILES[*]}"

# Tier 3 cross-check
PHASE_COMMITS=$(git log --oneline --all --grep="${PADDED_PHASE}" --format="%H" 2>/dev/null)
DIFF_BASE=""
if [ -n "$PHASE_COMMITS" ]; then
  DIFF_BASE=$(echo "$PHASE_COMMITS" | tail -1)^
  git rev-parse "${DIFF_BASE}" >/dev/null 2>&1 || DIFF_BASE=$(echo "$PHASE_COMMITS" | tail -1)
fi
echo "DIFF_BASE=$DIFF_BASE"
DIFF_FILES=$(git diff --name-only "${DIFF_BASE}..HEAD" -- . \
  ':!.planning/' ':!ROADMAP.md' ':!STATE.md' \
  ':!*-SUMMARY.md' ':!*-VERIFICATION.md' ':!*-PLAN.md' \
  ':!package-lock.json' ':!yarn.lock' ':!Gemfile.lock' ':!poetry.lock' 2>/dev/null)
echo "DIFF_FILES: $DIFF_FILES"
MISSING=()
while IFS= read -r file; do
  [ -z "$file" ] && continue
  printf '%s\n' "${REVIEW_FILES[@]}" | grep -Fxq -- "$file" 2>/dev/null || { MISSING+=("$file"); REVIEW_FILES+=("$file"); }
done <<< "$DIFF_FILES"
[ ${#MISSING[@]} -gt 0 ] && { echo "Warning: SUMMARY scope missing ${#MISSING[@]} file(s), added:"; printf '  - %s\n' "${MISSING[@]}"; }

# Post-processing: filter deleted, dedupe, sort
EXISTING=(); DELETED=0
for f in "${REVIEW_FILES[@]}"; do [ -f "$f" ] && EXISTING+=("$f") || DELETED=$((DELETED+1)); done
[ $DELETED -gt 0 ] && echo "Filtered $DELETED deleted files"
DEDUPED=()
while IFS= read -r l; do [ -n "$l" ] && DEDUPED+=("$l"); done < <(printf '%s\n' "${EXISTING[@]}" | sort -u)
echo ""
echo "FINAL SCOPE (${#DEDUPED[@]} files, tier=SUMMARY.md, depth=$REVIEW_DEPTH):"
printf '  - %s\n' "${DEDUPED[@]}"
